    entries_raw = document["resolutions"]
    if not isinstance(entries_raw, list) or not (
        AUTO_RESOLVE_BATCH_MIN <= len(entries_raw) <= AUTO_RESOLVE_BATCH_MAX
    ):
        raise ValueError("resolutions must be a list of 1-100 entries")

